            if value == color and start is None:
                start = i
            elif value != color and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != background and grid[r][c] not in marker_colors]

    # Each seed extends toward a marker in its row or column; the seed becomes 4.
    for r, c, color in seeds:
        candidates = []
        for cc in range(w):
            if grid[r][cc] in marker_colors:
                candidates.append((abs(cc-c), r, cc))
        for rr in range(h):
            if grid[rr][c] in marker_colors:
                candidates.append((abs(rr-r), rr, c))
        if not candidates:
            continue
        _, tr, tc = min(candidates)
        out[r][c] = 4
        dr = 0 if tr == r else (1 if tr > r else -1)
        dc = 0 if tc == c else (1 if tc > c else -1)
        rr, cc = r + dr, c + dc
        while (rr, cc) != (tr, tc):
            if grid[rr][cc] == background:
                out[rr][cc] = color
            rr += dr
            cc += dc

